import { escapeHtml } from './format';

export interface MarkdownHeading {
  level: number;
  id: string;
  text: string;
}

export interface RenderedMarkdown {
  html: string;
  headings: MarkdownHeading[];
}

function inlineMarkdown(value: string): string {
  return escapeHtml(value)
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+|\.?\.?\/[^\s)]+|#[^\s)]+)\)/g, '<a href="$2">$1</a>');
}

function slugify(value: string, sequence: number): string {
  const slug = value.toLowerCase().replace(/`/g, '').replace(/[^\p{Letter}\p{Number}]+/gu, '-').replace(/^-|-$/g, '');
  return slug || `section-${sequence}`;
}

function isTableDivider(line: string): boolean {
  return /^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(line);
}

function tableCells(line: string): string[] {
  return line.trim().replace(/^\||\|$/g, '').split('|').map((cell) => cell.trim());
}

export function renderMarkdown(source: string): RenderedMarkdown {
  const lines = source.replace(/\r\n?/g, '\n').split('\n');
  const headings: MarkdownHeading[] = [];
  const ids = new Map<string, number>();
  const output: string[] = [];
  const at = (position: number): string => lines[position] ?? '';
  let index = 0;

  while (index < lines.length) {
    const line = at(index);
    if (!line.trim()) { index += 1; continue; }

    if (line.startsWith('```')) {
      const language = line.slice(3).trim();
      const code: string[] = [];
      index += 1;
      while (index < lines.length && !at(index).startsWith('```')) code.push(at(index++));
      index += 1;
      output.push(`<pre><code${language ? ` data-language="${escapeHtml(language)}"` : ''}>${escapeHtml(code.join('\n'))}</code></pre>`);
      continue;
    }

    const heading = /^(#{1,3})\s+(.+)$/.exec(line);
    if (heading) {
      const level = (heading[1] ?? '#').length;
      const text = (heading[2] ?? '').trim();
      const base = slugify(text, headings.length + 1);
      const count = ids.get(base) ?? 0;
      ids.set(base, count + 1);
      const id = count ? `${base}-${count + 1}` : base;
      headings.push({ level, id, text });
      output.push(`<h${level} id="${id}">${inlineMarkdown(text)}</h${level}>`);
      index += 1;
      continue;
    }

    if (line.startsWith('> ')) {
      const quote: string[] = [];
      while (index < lines.length && at(index).startsWith('> ')) quote.push(at(index++).slice(2));
      output.push(`<blockquote>${quote.map(inlineMarkdown).join('<br>')}</blockquote>`);
      continue;
    }

    if (index + 1 < lines.length && line.includes('|') && isTableDivider(at(index + 1))) {
      const headers = tableCells(line);
      index += 2;
      const rows: string[][] = [];
      while (index < lines.length && at(index).includes('|') && at(index).trim()) rows.push(tableCells(at(index++)));
      output.push(`<div class="markdown-table"><table><thead><tr>${headers.map((cell) => `<th>${inlineMarkdown(cell)}</th>`).join('')}</tr></thead><tbody>${rows.map((row) => `<tr>${row.map((cell) => `<td>${inlineMarkdown(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);
      continue;
    }

    const unordered = /^-\s+(.+)$/.exec(line);
    const ordered = /^\d+\.\s+(.+)$/.exec(line);
    if (unordered || ordered) {
      const tag = unordered ? 'ul' : 'ol';
      const matcher = unordered ? /^-\s+(.+)$/ : /^\d+\.\s+(.+)$/;
      const items: string[] = [];
      while (index < lines.length) {
        const match = matcher.exec(at(index));
        if (!match) break;
        items.push(`<li>${inlineMarkdown(match[1] ?? '')}</li>`);
        index += 1;
      }
      output.push(`<${tag}>${items.join('')}</${tag}>`);
      continue;
    }

    const paragraph: string[] = [line.trim()];
    index += 1;
    while (index < lines.length && at(index).trim()
      && !/^(#{1,3})\s+/.test(at(index))
      && !at(index).startsWith('```')
      && !at(index).startsWith('> ')
      && !/^-\s+/.test(at(index))
      && !/^\d+\.\s+/.test(at(index))
      && !(index + 1 < lines.length && at(index).includes('|') && isTableDivider(at(index + 1)))) {
      paragraph.push(at(index++).trim());
    }
    output.push(`<p>${inlineMarkdown(paragraph.join(' '))}</p>`);
  }

  return { html: output.join('\n'), headings };
}
